render_chart <- function(data, cfg, manifest) { chart_validate_columns(data, list(group = cfg$x, before = cfg$y, after = cfg$group), c("group", "before", "after")); long <- rbind(data.frame(group = data[[cfg$x]], time = "之前", value = data[[cfg$y]]), data.frame(group = data[[cfg$x]], time = "之后", value = data[[cfg$group]])); p <- ggplot2::ggplot(long, ggplot2::aes(x = time, y = value, group = group, colour = group)) + ggplot2::geom_line() + ggplot2::geom_point(size = 2.8) + ggplot2::theme_minimal(base_size = 12) + ggplot2::theme(legend.position = "none") + ggplot2::labs(title = cfg$title %||% NULL, x = NULL, y = "数值"); chart_open_device(cfg$outputPath, cfg$format); print(p); grDevices::dev.off(); cfg$outputPath }
